# frozen_string_literal: true

# Homebrew cask for Otium.app. Generated by `scripts/package-otium.sh VERSION` in
# atrium-solutions/otium-app (private) from that release's SHA256SUMS — edit the template in
# packaging/brew/, not this file.
#
# Apple Silicon only: the bundled llama-server is built for arm64 with Metal. The app is
# ad-hoc signed, not notarised, so the postflight clears the download quarantine and the
# caveats say so.
cask "otium" do
  version "0.1.21"
  sha256 "76b2a53644eb34fd2fa74b9c54a8511ee61d27a6d0a08b1d8b7f94521024ec66"

  url "https://github.com/atrium-solutions/otium-releases/releases/download/v0.1.21/Otium-macos.zip"
  name "Otium"
  desc "Office AI chat served by your office's own idle computers"
  homepage "https://github.com/atrium-solutions/otium-releases"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on arch: :arm64

  # Otium updates itself from the office server once the admin approves a release, so
  # `brew upgrade` leaves it alone (`brew upgrade --greedy` still updates it).
  auto_updates true

  app "Otium.app"

  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/Otium.app"]
  end

  uninstall launchctl: ["ai.otium.app", "ai.otium.check"],
            quit:      "ai.otium.app",
            trash:     "~/Library/LaunchAgents/ai.otium.check.plist"

  zap trash: [
    "~/.otium",
    "~/Library/Application Support/ai.otium.app",
    "~/Library/Application Support/Otium",
    "~/Library/LaunchAgents/ai.otium.app.plist",
  ]

  caveats <<~EOS
    Otium #{version} is not Apple-notarised; macOS cannot name the developer. If it is
    still blocked, open it once with right-click → Open, or run:
      xattr -dr com.apple.quarantine "#{appdir}/Otium.app"

    On first launch, choose: join your office, run the office server, or just chat.
    On the office server, Otium installs and runs web search (SearXNG) itself on first
    start (about a minute; it needs the internet once). No container is needed.
    `brew uninstall --zap --cask otium` also removes the office data on this Mac,
    including an office server's certificate authority — back it up first.
  EOS
end
